package com.zhuqiyun.procurement;
import com.zhuqiyun.platform.*;import com.zhuqiyun.finance.FinanceService;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import static com.zhuqiyun.domain.Rules.*;
/** Foreign-key trace, paginated in SQL before loading document lines. */
@Service
public class TraceService {
 private final Db db;private final Auth auth;private final ProcurementService procurement;private final FinanceService finance;
 public TraceService(Db db,Auth auth,ProcurementService procurement,FinanceService finance){this.db=db;this.auth=auth;this.procurement=procurement;this.finance=finance;}
 private String literal(String v){return "'"+v.replace("'","''")+"'";}
 private void add(List<String> queries,String kind,String label,String code,String time,String operator,String status,String reason,String amount,String path,String from,String where){queries.add("SELECT CONCAT('"+kind+"-',t.id) event_key,"+literal(label)+" label,"+code+" code,"+time+" created_at,"+operator+" operator_id,"+status+" status,"+reason+" reason,"+amount+" amount,"+path+" path,"+literal(kind)+" kind,t.id source_id "+from+" WHERE "+where+" AND "+time+" IS NOT NULL");}
 private String path(String base,long id){return literal(base+id);}
 private void request(List<String> queries,long id){if(!auth.can("request:read"))return;
  add(queries,"request","采购申请创建","t.code","t.created_at","t.applicant_id","NULL","t.note","t.total_amount",path("/requests/",id),"FROM purchase_requests t","t.id="+id+" AND t.tenant_id=1");
  add(queries,"approval","采购审批记录","r.code","t.created_at","t.operator_id","t.decision","t.comment","NULL","CONCAT('/requests/"+id+"?tab=approvals&approval_id=',t.id)","FROM approvals t JOIN purchase_requests r ON r.id=t.request_id","t.request_id="+id+" AND t.tenant_id=1");
  if(auth.can("quote:read"))add(queries,"quote","供应商报价","s.name","t.created_at","(SELECT a.operator_id FROM audit_logs a WHERE a.entity_type='quote' AND a.entity_id=t.id AND a.action='RECORD_QUOTE' ORDER BY a.id LIMIT 1)","NULL","t.note","t.total_amount","CONCAT('/requests/"+id+"?tab=quotes&quote_id=',t.id)","FROM quotes t JOIN suppliers s ON s.id=t.supplier_id","t.request_id="+id+" AND t.tenant_id=1");
 }
 private List<Map<String,Object>> lines(String kind,long id){String sql=switch(kind){case "request","replacement"->"SELECT i.quantity,m.name material_name,m.specification,m.unit FROM request_items i JOIN materials m ON m.id=i.material_id WHERE i.request_id=?";case "quote"->"SELECT r.quantity,m.name material_name,m.specification,m.unit FROM quote_items i JOIN request_items r ON r.id=i.request_item_id JOIN materials m ON m.id=r.material_id WHERE i.quote_id=?";case "order"->"SELECT i.quantity,m.name material_name,m.specification,m.unit FROM order_items i JOIN materials m ON m.id=i.material_id WHERE i.order_id=?";case "receipt"->"SELECT i.quantity,m.name material_name,m.specification,m.unit FROM receipt_items i JOIN materials m ON m.id=i.material_id WHERE i.receipt_id=?";case "return"->"SELECT i.quantity,m.name material_name,m.specification,m.unit FROM purchase_return_items i JOIN receipt_items r ON r.id=i.receipt_item_id JOIN materials m ON m.id=r.material_id WHERE i.return_id=?";case "issue-flow"->"SELECT ABS(i.quantity) quantity,m.name material_name,m.specification,m.unit FROM stock_movements i JOIN materials m ON m.id=i.material_id WHERE i.id=?";default->null;};return sql==null?List.of():db.list(sql,id);}
 private Map<String,Object> finish(Map<String,Object> result,List<String> queries,int page,int size){Fields.check(page>=1&&page<=100000&&size>=1&&size<=100,"分页参数无效");if(queries.isEmpty()){result.putAll(row("events",List.of(),"total",0,"page",page,"size",size));return result;}String union="("+String.join(" UNION ALL ",queries)+") e";long total=((Number)db.one("SELECT COUNT(*) total FROM "+union).get("total")).longValue();var rows=db.list("SELECT e.*,u.name operator_name FROM "+union+" LEFT JOIN users u ON u.id=e.operator_id ORDER BY e.created_at DESC,e.event_key LIMIT ? OFFSET ?",size,(long)(page-1)*size);for(var r:rows){r.put("id",r.remove("event_key"));r.put("lines",lines(r.get("kind").toString(),((Number)r.get("source_id")).longValue()));if(r.get("amount")==null)r.remove("amount");}result.putAll(row("events",rows,"total",total,"page",page,"size",size));return result;}
 @Transactional(readOnly=true) public Map<String,Object> order(long id,int page,int size){var o=procurement.orderDetail(id);long request=((Number)o.get("request_id")).longValue();List<String> queries=new ArrayList<>();request(queries,request);List<Map<String,Object>> links=new ArrayList<>();
  add(queries,"order","授予并生成采购订单","t.code","t.created_at","t.buyer_id","NULL","q.selection_reason","t.total_amount",path("/orders/",id),"FROM purchase_orders t JOIN quotes q ON q.id=t.quote_id","t.id="+id+" AND t.tenant_id=1");
  add(queries,"closure","CANCELLED".equals(o.get("status"))?"取消订单":"关闭剩余采购","t.code","t.closed_at","t.closed_by","t.status","t.close_reason","t.closed_amount",path("/orders/",id),"FROM purchase_orders t","t.id="+id+" AND t.tenant_id=1");
  if(auth.can("inventory:read"))add(queries,"receipt","分批验收入库","t.code","t.created_at","t.operator_id","NULL","t.note","t.amount","CONCAT('/orders/"+id+"?tab=receipts&receipt_id=',t.id)","FROM receipts t","t.order_id="+id+" AND t.tenant_id=1");
  add(queries,"return","采购退货","t.code","t.created_at","t.operator_id","NULL","t.reason","t.amount","CONCAT('/orders/"+id+"?tab=returns&purchase_return_id=',t.id)","FROM purchase_returns t","t.order_id="+id+" AND t.tenant_id=1");
  if(auth.can("finance:read")){
   add(queries,"payment-review","付款申请操作","CONCAT('申请 #',a.id)","t.created_at","t.operator_id","t.decision","t.comment","a.amount","CONCAT('/finance?tab=applications&application_id=',a.id)","FROM payment_application_records t JOIN payment_applications a ON a.id=t.application_id JOIN payables v ON v.id=a.payable_id","v.order_id="+id+" AND t.tenant_id=1");
   add(queries,"payment-app","付款申请历史记录（未留独立审批明细）","CONCAT('申请 #',t.id)","t.created_at","t.applicant_id","NULL","t.note","t.amount","CONCAT('/finance?tab=applications&application_id=',t.id)","FROM payment_applications t JOIN payables v ON v.id=t.payable_id","v.order_id="+id+" AND t.tenant_id=1 AND NOT EXISTS(SELECT 1 FROM payment_application_records r WHERE r.application_id=t.id)");
   add(queries,"payment","登记实际付款","t.reference","t.created_at","t.operator_id","NULL","t.note","t.amount","CONCAT('/finance?tab=payments&payment_id=',t.id)","FROM payments t JOIN payables v ON v.id=t.payable_id","v.order_id="+id+" AND t.tenant_id=1");
   add(queries,"refund","登记供应商退款","t.reference","t.created_at","t.operator_id","NULL","t.note","t.amount","CONCAT('/finance?tab=refunds&refund_id=',t.id)","FROM supplier_refunds t JOIN payables v ON v.id=t.payable_id","v.order_id="+id+" AND t.tenant_id=1");
  }
  if(auth.can("inventory:read")){
   String from="FROM stock_movements t JOIN order_items oi ON oi.id=t.source_order_item_id JOIN issues i ON i.id=t.issue_id LEFT JOIN issue_returns r ON r.id=t.issue_return_id";
   add(queries,"issue-flow","明确来源的项目领料","i.code","t.created_at","t.operator_id","NULL","t.reference",auth.can("cost:read")?"t.amount":"NULL","CONCAT('/inventory?tab=issues&issue_id=',i.id)",from,"oi.order_id="+id+" AND t.kind='ISSUE' AND t.tenant_id=1");
   add(queries,"issue-flow","明确来源的项目退料","r.code","t.created_at","t.operator_id","NULL","r.reason",auth.can("cost:read")?"t.amount":"NULL","CONCAT('/inventory?tab=returns&return_id=',r.id)",from,"oi.order_id="+id+" AND t.kind='ISSUE_RETURN' AND t.tenant_id=1");
  }
  if(auth.can("request:read")&&o.get("replacement_request_id")!=null){long rid=((Number)o.get("replacement_request_id")).longValue();add(queries,"replacement","补采草稿生成","t.code","t.created_at","t.applicant_id","NULL","t.note","t.total_amount",path("/requests/",rid),"FROM purchase_requests t","t.id="+rid+" AND t.tenant_id=1");links.add(row("id",rid,"label","补采申请 #"+rid,"path","/requests/"+rid));}
  var summary=row("order_code",o.get("code"),"project_name",o.get("project_name"),"status",o.get("status"),"original_amount",o.get("total_amount"),"closed_amount",o.get("closed_amount"),"return_amount",o.get("return_amount"),"effective_amount",o.get("effective_amount"));if(auth.can("finance:read"))summary.put("payable",finance.payableView(((Number)((Map<?,?>)o.get("payable")).get("id")).longValue()));
  return finish(row("access",DataPolicy.flags(auth),"summary",summary,"order_items",o.get("items"),"links",links,"source_notice","历史领料未明确指定采购来源时，不按材料或项目相同推断关联。采购退货不恢复待履行数量；补采须新申请。"),queries,page,size);
 }
 @Transactional(readOnly=true) public Map<String,Object> request(long id,int page,int size){var r=procurement.detail(id);if(auth.can("order:read")){var orders=db.list("SELECT id FROM purchase_orders WHERE request_id=? AND tenant_id=1",id);if(!orders.isEmpty())return order(((Number)orders.get(0).get("id")).longValue(),page,size);}List<String> queries=new ArrayList<>();request(queries,id);List<Map<String,Object>> links=new ArrayList<>();if(auth.can("order:read")&&r.get("source_order_id")!=null)links.add(row("id",r.get("source_order_id"),"label","补采来源 "+r.get("source_order_code"),"path","/orders/"+r.get("source_order_id")));return finish(row("access",DataPolicy.flags(auth),"summary",row("request_code",r.get("code"),"project_name",r.get("project_name"),"status",r.get("status"),"request_amount",r.get("total_amount")),"order_items",List.of(),"links",links),queries,page,size);}
}
